#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-26
# Upgrade a FISH Isaac image (rmw_fastrtps) with the "fastdds1" identity layer (docker/overlay_patches/fastdds1_identity.py):
#   1. rmw_fastrtps_shared_cpp 6.2.10 sources (host clone, RMW_FASTRTPS_SRC) into the overlay workspace, patch tracetools +
#      rmw_fastrtps_shared_cpp, colcon build both; /opt's librmw_fastrtps_cpp.so has no RPATH, so the overlay's LD_LIBRARY_PATH
#      selects the patched shared lib (verified with ldd).
#   2. in-place rebuild of the packages that instantiate header-level hooks, with the regex FIXED: migrate_overlay.sh looked for
#      use_intra_process_comms (plural) and missed NITROS's SubscriptionOptions.use_intra_process_comm (singular) — that is why
#      Isaac sessions had 72k fish_rclcpp_intra_publish but 20 fish_rclcpp_intra_take (TASK 4 apriltag session, 2026-10-26).
#   3. functional test inside the container: lttng + ros2 topic pub/echo (rclpy -> rmw_fastrtps_cpp -> the overlay shared lib),
#      every fish_rmw_take_id must match a fish_rmw_write by (guid, seq).
#   4. docker commit <new> (ENTRYPOINT [], see feedback_migrated_image_entrypoint) — only if 1 and 3 passed. Old tags untouched.
# Usage: scripts/migrate_fastdds_identity.sh <base_image[:tag]> <new_image:tag> [extra packages to rebuild in place ...]
#   env: RMW_FASTRTPS_SRC (default ~/fish_traces/rmw_fastrtps_src/rmw_fastrtps), LOG (default /tmp/migrate_fastdds_<tag>.log), KEEP=1
set -u
BASE=$1; NEW=$2; shift 2; EXTRA_PKGS="$*"
HERE=$(cd "$(dirname "$0")/.." && pwd)
SRC=${RMW_FASTRTPS_SRC:-$HOME/fish_traces/rmw_fastrtps_src/rmw_fastrtps}
TAG=$(echo "$NEW" | tr ':/' '__'); C=migf_$TAG; LOG=${LOG:-/tmp/migrate_fastdds_$TAG.log}
[ -d "$SRC/rmw_fastrtps_shared_cpp" ] || { echo "rmw_fastrtps source missing: $SRC" | tee "$LOG"; exit 2; }
docker rm -f $C >/dev/null 2>&1
docker run -d --name $C --entrypoint bash -v "$HERE/docker/overlay_patches":/patches:ro -v "$HERE/scripts":/fish_scripts:ro \
  -v "$SRC":/rmw_fastrtps_src:ro "$BASE" -c 'sleep 21600' >/dev/null || { echo "cannot start $BASE" | tee "$LOG"; exit 2; }
{
echo "=== $(date +%T) fastdds1: $BASE -> $NEW"
# 1. sources + patch + build
docker exec $C bash -c '
  set -e; W=/root/trace_overlay_ws; cd $W/src
  [ -f /opt/ros/humble/share/rmw_fastrtps_shared_cpp/package.xml ] || { echo "NO_FASTRTPS_IN_IMAGE"; exit 3; }
  VI=$(grep -o "<version>[^<]*" /opt/ros/humble/share/rmw_fastrtps_shared_cpp/package.xml | cut -d">" -f2)
  VS=$(grep -o "<version>[^<]*" /rmw_fastrtps_src/rmw_fastrtps_shared_cpp/package.xml | cut -d">" -f2)
  echo "rmw_fastrtps_shared_cpp: image $VI, source $VS"; [ "$VI" = "$VS" ] || echo "WARNING: version mismatch"
  rm -rf rmw_fastrtps_shared_cpp; cp -r /rmw_fastrtps_src/rmw_fastrtps_shared_cpp .
  python3 /patches/fastdds1_identity.py $W/src
  set +u; source /opt/ros/humble/setup.bash; set -u
  cd $W && colcon build --packages-select tracetools rmw_fastrtps_shared_cpp --cmake-args -DCMAKE_BUILD_TYPE=RelWithDebInfo -DBUILD_TESTING=OFF 2>&1 | tail -12
  grep -q "fish_rmw_take_id" $W/install/tracetools/include/tracetools/tracetools/tracetools.h && echo FASTDDS_MARKER_OK || echo FASTDDS_MARKER_MISSING
  set +u; source $W/install/setup.bash; set -u
  echo "ldd: $(ldd /opt/ros/humble/lib/librmw_fastrtps_cpp.so | grep rmw_fastrtps_shared_cpp)"
  echo "overlay shared lib hooks: $(strings $W/install/rmw_fastrtps_shared_cpp/lib/librmw_fastrtps_shared_cpp.so | grep -c "fish_rmw_write\|fish_rmw_take_id")"
'
echo "=== $(date +%T) step 1 done"
# 2. header-hook users, in place. Selection by symbol table (2026-10-26): every workspace library that instantiates
#    rclcpp::experimental::SubscriptionIntraProcess<...>::take_data (nm, demangled) but does not reference the hook
#    ros_trace_fish_rclcpp_intra_take needs a rebuild against the overlay headers — the subscriptions of a NITROS node are
#    instantiated in the NODE library (librectify_node.so ...), not in libisaac_ros_nitros.so. Test-only libraries (object dir
#    under <target>.dir/test/) are skipped: BUILD_TESTING=OFF never rebuilds them and no benchmark loads them. The regex users
#    and EXTRA_PKGS are added for safety.
docker exec -e EXTRA_PKGS="$EXTRA_PKGS" $C bash -c '
  set +u; source /opt/ros/humble/setup.bash; set -u
  WS=""; for w in /root/ros_ws /workspaces/isaac_ros-dev; do [ -z "$WS" ] && [ -d $w/src ] && [ -d $w/install ] && WS=$w; done
  [ -n "$WS" ] || { echo "no source workspace: header-hook users not rebuilt"; exit 0; }
  scan() {   # "<pkg> <lib>" for every non-test lib with the take_data instantiation and no hook reference
    for so in $WS/install/*/lib/*.so $WS/install/*/lib/*/*.so; do [ -f "$so" ] || continue
      nm -DC --defined-only "$so" 2>/dev/null | grep -q "SubscriptionIntraProcess<.*>::take_data" || continue
      nm -D --undefined-only "$so" 2>/dev/null | grep -q "ros_trace_fish_rclcpp_intra_take" && continue
      pkg=$(echo "$so" | sed "s|$WS/install/||" | cut -d/ -f1); tgt=$(basename "$so" .so); tgt=${tgt#lib}
      [ -d "$WS/build/$pkg/CMakeFiles/$tgt.dir/test" ] && continue
      echo "$pkg $so"; done; }
  NEED=$(scan); echo "libs instantiating the intra-process take without the hook (non-test): $(echo "$NEED" | grep -c .)"; echo "$NEED" | sed "s|^|  |" | head -40
  USERS=$(grep -rlE "create_generic_subscription|GenericSubscription|use_intra_process_comm" --include=*.cpp --include=*.hpp $WS/src 2>/dev/null | sed "s|$WS/src/||" | awk -F/ "{print \$1\"/\"\$2}" | sort -u | while read d; do p=$(grep -o "<name>[^<]*" $WS/src/$d/package.xml 2>/dev/null | head -1 | cut -d">" -f2); [ -n "$p" ] && echo $p; done | sort -u | grep -v example | tr "\n" " ")
  PK="$(echo $USERS $EXTRA_PKGS $(echo "$NEED" | awk "{print \$1}") | tr " " "\n" | grep . | sort -u | tr "\n" " ")"
  echo "header-hook users rebuilt in place in $WS: $PK"
  set +u; source $WS/install/setup.bash; source /root/trace_overlay_ws/install/setup.bash; set -u
  cd $WS && colcon build --packages-select $PK --continue-on-error --cmake-args -DBUILD_TESTING=OFF -DCMAKE_BUILD_TYPE=Release 2>&1 | tail -10
  for p in $PK; do
    grep -q "^rclcpp_DIR:PATH=/root/trace_overlay_ws/install/rclcpp/" build/$p/CMakeCache.txt 2>/dev/null && ok="overlay rclcpp OK" || ok="WARNING overlay rclcpp NOT used"
    n=$(cat install/$p/lib/*.so install/$p/lib/*/*.so 2>/dev/null | strings | grep -c "fish_rclcpp_intra_take"); echo "[inplace] $p: $ok, intra_take hook refs: $n"
  done
  LEFT=$(scan); echo "after the rebuild, non-test libs still without the hook: $(echo "$LEFT" | grep -c .)"; echo "$LEFT" | sed "s|^|  |" | head -20
  python3 - "$PK" <<PY
import json, os, sys, time
m = "/root/trace_overlay_ws/fish_rebuilt_packages.json"; d = json.load(open(m)) if os.path.exists(m) else {"rebuilt": {}}
d.setdefault("rebuilt_in_place", {}).update({p: {"ws": "$WS", "at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), "overlay": "fastdds1"} for p in sys.argv[1].split()})
json.dump(d, open(m, "w"), indent=1)
PY
'
echo "=== $(date +%T) step 2 done"
# 3. functional test: the two events must pair by (guid, seq)
docker exec $C bash -c '
  set +u; source /opt/ros/humble/setup.bash; source /root/trace_overlay_ws/install/setup.bash; set -u
  export ROS_DOMAIN_ID=73 RMW_IMPLEMENTATION=rmw_fastrtps_cpp
  lttng-sessiond --daemonize >/dev/null 2>&1; sleep 1
  lttng destroy fishtest >/dev/null 2>&1; rm -rf /tmp/fishtest_trace
  lttng create fishtest -o /tmp/fishtest_trace >/dev/null
  lttng enable-event -u ros2:fish_rmw_write,ros2:fish_rmw_take_id,ros2:rmw_take >/dev/null
  lttng add-context -u -t vpid -t vtid >/dev/null; lttng start >/dev/null
  timeout 14 /opt/ros/humble/bin/ros2 topic echo /fish_id_test std_msgs/msg/String >/dev/null 2>&1 &
  sleep 3; timeout 8 /opt/ros/humble/bin/ros2 topic pub -r 20 /fish_id_test std_msgs/msg/String "{data: x}" >/dev/null 2>&1
  wait; lttng stop >/dev/null; lttng destroy fishtest >/dev/null
  babeltrace2 /tmp/fishtest_trace > /tmp/fishtest.txt 2>/dev/null
  python3 - <<PY
import re
w, t, rt_ok, n_rmw = set(), [], 0, 0
for line in open("/tmp/fishtest.txt"):
    f = dict(re.findall(r"(\w+) = (0x[0-9A-Fa-f]+|-?\d+)", line))
    if "fish_rmw_write" in line: w.add((f.get("guid_hi"), f.get("guid_lo"), f.get("seq")))
    elif "fish_rmw_take_id" in line:
        t.append((f.get("guid_hi"), f.get("guid_lo"), f.get("seq"))); rt_ok += int(f.get("reception_timestamp", "0")) > 0
    elif "ros2:rmw_take" in line: n_rmw += 1
m = sum(1 for x in t if x in w)
print(f"FASTDDS_TEST writes={len(w)} takes={len(t)} matched={m} reception_ts_nonzero={rt_ok} rmw_take={n_rmw}")
PY
  pkill -f lttng-sessiond; rm -rf /tmp/fishtest_trace /tmp/fishtest.txt
'
echo "=== $(date +%T) step 3 done"
} > "$LOG" 2>&1
M=$(grep -o "FASTDDS_TEST .*matched=[0-9]*" "$LOG" | grep -o "matched=[0-9]*" | cut -d= -f2)
if grep -q "FASTDDS_MARKER_OK" "$LOG" && ! grep -q "Failed   <<<\|Aborted  <<<" "$LOG" && [ -n "$M" ] && [ "$M" -gt 0 ]; then
  # docker 29.3: `commit --change 'ENTRYPOINT []'` does NOT clear the container's --entrypoint bash (image keeps ["bash"], rc 126 on
  # `bash -lc`); a one-line Dockerfile build from the committed image does. Commit to a temp tag, build the final tag, drop the temp tag.
  docker commit --change 'CMD ["bash","-c","sleep 10800"]' --change "LABEL fish.lineage=mainline" \
    --change "LABEL fish.overlay=fw28-transplant+fastdds1" --change "LABEL fish.migrated_from=$BASE" $C "$NEW-entrybash" >> "$LOG" 2>&1 \
    && printf 'FROM %s\nENTRYPOINT []\nCMD ["bash","-c","sleep 10800"]\n' "$NEW-entrybash" | docker build -q -t "$NEW" - >> "$LOG" 2>&1 \
    && docker rmi "$NEW-entrybash" >> "$LOG" 2>&1 \
    && [ "$(docker inspect --format '{{json .Config.Entrypoint}}' "$NEW")" = null ] && echo COMMITTED >> "$LOG"
else
  echo "NOT COMMITTED (marker / build / pairing test failed)" >> "$LOG"
fi
[ "${KEEP:-0}" = 1 ] && echo "container $C kept for inspection" >> "$LOG" || docker rm -f $C >/dev/null 2>&1; echo DONE >> "$LOG"; tail -4 "$LOG"
